package com.jgeted.sagadyssey.social.needs;
import com.jgeted.sagadyssey.npc.brain.fieldwork.FieldworkStorage;
import com.jgeted.sagadyssey.social.production.*;
import com.jgeted.sagadyssey.worldsim.rights.*;
import com.jgeted.sagadyssey.worldsim.transfer.TransferIntent;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class CancelledSupplyHistoryTest {
    private ProductionOrder order(){var owner=SubjectRef.character(UUID.randomUUID());return ProductionOrder.open(UUID.randomUUID(),owner,owner,"sagadyssey:iron_pickaxe",List.of(new ProductionMaterial(new ItemFingerprint("minecraft:iron_ingot",0),6),new ProductionMaterial(new ItemFingerprint("minecraft:coal",0),2)),new ProductionMaterial(new ItemFingerprint("minecraft:iron_pickaxe",0),2),80,UUID.randomUUID(),"minecraft:overworld",BlockPos.ZERO,UUID.randomUUID(),"minecraft:overworld",BlockPos.ZERO,1,"original two-tool request");}
    @Test void cancelledHistoryIsTerminalAndCannotBeReusedAsAReplacementOrder(){var d=new ProductionOrderData();var a=order();d.put(a);var cancelled=a.transition(ProductionOrderStatus.CANCELLED,2,"before work");d.put(cancelled);assertEquals(cancelled,d.byId(a.id()).orElseThrow());assertThrows(IllegalStateException.class,()->d.put(a));assertThrows(IllegalStateException.class,()->cancelled.claim(UUID.randomUUID(),3,"retry"));}
    @Test void originalDemandAndLinkSurviveNbtWithoutErasingUnfulfilledTwoTools(){var owner=SubjectRef.character(UUID.randomUUID());var dest=new FieldworkStorage("minecraft:overworld",BlockPos.ZERO,UUID.randomUUID(),owner,AccessPolicy.PRIVATE,TransferIntent.DELIVERY,"initial");var f=new SupplyFlowData();f.register(dest);var n=new NeedRequestData();var r=n.openOrUpdate(new NeedRequest.Key(owner.id(),"CHARACTER:original",new ItemFingerprint("minecraft:iron_pickaxe",0),dest.containerId(),1,10000),2,32,1);f.demand(r.id(),owner,dest.containerId());var order=UUID.randomUUID();f.production(r.id(),order);var rf=SupplyFlowData.load(f.save(new CompoundTag(),null),null);var rn=NeedRequestData.load(n.save(new CompoundTag(),null),null);assertEquals(order,rf.production(r.id()));assertEquals(2,rn.request(r.id()).requested());assertEquals(2,rn.request(r.id()).remaining());assertEquals(0,rn.request(r.id()).delivered());}
    @Test void immutableHistoricalLinkIsNotClearedOrReplacedToEnableRecovery(){var f=new SupplyFlowData();var owner=SubjectRef.character(UUID.randomUUID());var dest=new FieldworkStorage("minecraft:overworld",BlockPos.ZERO,UUID.randomUUID(),owner,AccessPolicy.PRIVATE,TransferIntent.DELIVERY,"initial");f.register(dest);UUID need=UUID.randomUUID(),old=UUID.randomUUID();f.demand(need,owner,dest.containerId());f.production(need,old);f.production(need,old);assertThrows(IllegalStateException.class,()->f.production(need,UUID.randomUUID()));assertEquals(old,f.production(need));}
    @Test void selectorOnlyChoosesFrozenCancellationCases(){var a=System.getProperty("sagadyssey.cancelled.enabled");var b=System.getProperty("sagadyssey.cancelled.phase");try{System.setProperty("sagadyssey.cancelled.enabled","true");System.setProperty("sagadyssey.cancelled.phase","cases");assertEquals(6,CancelledSupplyGameTests.tests().size());assertTrue(CancelledSupplyGameTests.tests().stream().allMatch(t->t.structureName().startsWith("sagadyssey_cancelled_recovery:")));System.setProperty("sagadyssey.cancelled.phase","recover");assertEquals(1,CancelledSupplyGameTests.tests().size());System.setProperty("sagadyssey.cancelled.phase","restart");assertEquals(1,CancelledSupplyGameTests.tests().size());}finally{if(a==null)System.clearProperty("sagadyssey.cancelled.enabled");else System.setProperty("sagadyssey.cancelled.enabled",a);if(b==null)System.clearProperty("sagadyssey.cancelled.phase");else System.setProperty("sagadyssey.cancelled.phase",b);}}
}
